// Turns TeleCRM search results into one batch for the dashboard.
// TeleCRM's API may not return a created time. Leads seen for the first time (after the first run)
// get the time n8n found them as Created On (at most ~30 min late). On the very first run nothing is
// dated, so older leads don't land on today. A TeleCRM export upload later fills exact times.
const sd = $getWorkflowStaticData('global');
const firstRun = !Array.isArray(sd.seen);
const seen = new Set(sd.seen || []);
const now = new Date().toISOString();
const leads = [];
for (const item of $input.all()) {
  const arr = Array.isArray(item.json.data) ? item.json.data : [item.json];
  for (const l of arr) {
    if (!l || !l.id) continue;
    const row = Object.assign({}, l.fields || {});
    row['Lead id'] = String(l.id);
    if (l.status !== undefined && row.status === undefined) row.status = l.status;
    if (l.rating !== undefined && row.rating === undefined) row.rating = l.rating;
    if (l.employeeid && row.assignee === undefined) row.assignee = l.employeeid;
    const hasCreated = Object.keys(row).some((k) => /created/i.test(k));
    if (!hasCreated && !firstRun && !seen.has(String(l.id))) row['Created On'] = now;
    leads.push(row);
    seen.add(String(l.id));
  }
}
sd.seen = Array.from(seen).slice(-20000);
return [{ json: { leads } }];
